#!/usr/bin/env python3
"""Mozilla CA bundle (PEM) -> ca_bundle.c for libwiitls (stdlib only).

  python tools/gen_ca_bundle.py --pem data/cacert.pem --sha256 data/cacert.pem.sha256 --out ca_bundle.c

Every root is stored as DER in .rodata. The table is sorted by the FNV-1a-32
hash of the subject DER (tag+length+value, as mbedtls' subject_raw), so the
CA callback can binary-search a child's issuer_raw.
"""
import argparse
import base64
import hashlib
import re
import sys

PEM_RE = re.compile(rb"-----BEGIN CERTIFICATE-----\r?\n(.*?)-----END CERTIFICATE-----", re.S)


def fnv1a32(data):
    h = 0x811C9DC5
    for b in data:
        h ^= b
        h = (h * 0x01000193) & 0xFFFFFFFF
    return h


def der_header(buf, off):
    """Returns (tag, header_len, value_len) of the TLV at off."""
    tag = buf[off]
    first = buf[off + 1]
    if first < 0x80:
        return tag, 2, first
    n = first & 0x7F
    if n == 0 or n > 4:
        raise ValueError("unsupported DER length")
    return tag, 2 + n, int.from_bytes(buf[off + 2:off + 2 + n], "big")


def subject_span(der):
    """(offset, length) of the subject TLV inside a DER certificate."""
    tag, hl, _ = der_header(der, 0)          # Certificate SEQUENCE
    if tag != 0x30:
        raise ValueError("not a certificate")
    off = hl
    tag, hl, _ = der_header(der, off)        # tbsCertificate SEQUENCE
    if tag != 0x30:
        raise ValueError("bad tbsCertificate")
    off += hl
    fields = []
    for _ in range(6):                        # [0] version?, serial, sigAlg, issuer, validity, subject
        tag, hl, vl = der_header(der, off)
        fields.append((tag, off, hl + vl))
        off += hl + vl
    if fields[0][0] != 0xA0:                  # v1 certificate: no explicit version
        fields.insert(0, None)
    tag, s_off, s_len = fields[5]
    if tag != 0x30:
        raise ValueError("bad subject")
    return s_off, s_len


def labels_and_ders(pem_bytes):
    out = []
    for m in PEM_RE.finditer(pem_bytes):
        before = pem_bytes[:m.start()].rstrip().split(b"\n")
        # cacert.pem: "<label>\n=====\n-----BEGIN..."
        label = before[-2].decode("utf-8", "replace").strip() if len(before) >= 2 else "?"
        out.append((label, base64.b64decode(b"".join(m.group(1).split()))))
    return out


def c_comment(s):
    return s.replace("*/", "* /")


def generate(pem_bytes, source_note):
    entries = []
    for label, der in labels_and_ders(pem_bytes):
        s_off, s_len = subject_span(der)
        if s_len > 0xFFFF or s_off > 0xFFFF:
            raise ValueError("subject offset/length exceeds uint16")
        entries.append((fnv1a32(der[s_off:s_off + s_len]), der, s_off, s_len, label))
    entries.sort(key=lambda e: (e[0], e[1]))

    lines = [
        "/* Generated by tools/gen_ca_bundle.py - do not edit. */",
        "/* " + c_comment(source_note) + " */",
        '#include "wtls_castore.h"',
        "",
    ]
    for i, (_, der, _, _, label) in enumerate(entries):
        lines.append(f"/* {c_comment(label)} */")
        lines.append(f"static const uint8_t ca_{i}[{len(der)}] = {{")
        for k in range(0, len(der), 16):
            lines.append("    " + ",".join(f"0x{b:02x}" for b in der[k:k + 16]) + ",")
        lines.append("};")
    lines.append("")
    lines.append("const wtls_ca_entry wtls_ca_bundle[] = {")
    for i, (h, der, s_off, s_len, _) in enumerate(entries):
        lines.append(f"    {{0x{h:08x}u, {s_off}, {s_len}, {len(der)}, ca_{i}}},")
    lines.append("};")
    lines.append(f"const size_t wtls_ca_bundle_count = {len(entries)};")
    lines.append("")
    return "\n".join(lines), len(entries)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--pem", required=True)
    ap.add_argument("--sha256", help="file whose first token is the expected SHA-256 of --pem")
    ap.add_argument("--out", required=True)
    args = ap.parse_args()
    pem = open(args.pem, "rb").read()
    digest = hashlib.sha256(pem).hexdigest()
    if args.sha256:
        want = open(args.sha256).read().split()[0].lower()
        if want != digest:
            sys.exit(f"gen_ca_bundle: SHA-256 mismatch for {args.pem}: {digest} != {want}")
    m = re.search(rb"Certificate data from Mozilla as of: ([^\n]*)", pem)
    note = f"source: cacert.pem sha256 {digest}"
    if m:
        note += ", Mozilla data as of " + m.group(1).decode().strip()
    text, n = generate(pem, note)
    with open(args.out, "w", newline="\n") as f:
        f.write(text)
    print(f"gen_ca_bundle: {n} roots -> {args.out}")


if __name__ == "__main__":
    main()
